// See SPEC.md for the exact conversion rules.
package md

import (
	"sort"
	"strings"
)

// ToHTML converts a Markdown-subset document to HTML.
func ToHTML(src string) string {
	var out strings.Builder
	for _, b := range parseBlocks(strings.Split(strings.TrimSuffix(src, "\n"), "\n")) {
		out.WriteString(b)
		out.WriteByte('\n')
	}
	return out.String()
}

func splitLines(src string) []string {
	lines := strings.Split(src, "\n")
	for i, l := range lines {
		lines[i] = strings.TrimSuffix(l, "\r")
	}
	return lines
}

// ---------- blocks ----------

func isBlank(l string) bool {
	return l == "" || l == strings.TrimSpace(l)
}

var escapeChars = `\\` + "`*_{}[]()#+-.!<>`"

// blockHTML renders the blocks in lines and returns them joined with "\n".
func blockHTML(lines []string) string {
	var out []string
	_ = parseBlocksInto(lines, &out)
	return strings.Join(out, "\n")
}

func parseBlocksInto(lines []string, out *[]string) bool {
	i := 0
	n := len(lines)
	for i < n {
		l := lines[i]
		if isBlank(l) {
			i++
			continue
		}
		if strings.HasPrefix(l, "```") {
			var content []string
			info := firstWord(strings.TrimSpace(l[3:]))
			i++
			for i < n && strings.TrimRight(lines[i], " ") != "```" {
				content = append(content, lines[i])
				i++
			}
			i++ // closing fence (or end of input)
			var b strings.Builder
			b.WriteString("<pre><code")
			if info != "" {
				b.WriteString(` class="language-`)
				b.WriteString(escapeText(info))
				b.WriteByte('"')
			}
			b.WriteString(">")
			for _, c := range content {
				b.WriteString(escapeText(c))
				b.WriteByte('\n')
			}
			b.WriteString("</code></pre>")
			*out = append(*out, b.String())
			continue
		}
		if h, ok := headingHTML(l); ok {
			*out = append(*out, h)
			i++
			continue
		}
		if isRule(l) {
			*out = append(*out, "<hr />")
			i++
			continue
		}
		if strings.HasPrefix(l, ">") {
			var q []string
			for i < n && strings.HasPrefix(lines[i], ">") {
				q = append(q, dropQuote(lines[i]))
				i++
			}
			*out = append(*out, "<blockquote>\n"+blockHTML(q)+"</blockquote>")
			continue
		}
