					// continuation of the last item
					it = it + contLine(l2)
					items[len(items)-1] = it
					i++
					continue
				}
				break
			}
			*out = append(*out, listHTML(items))
			continue
		}
		// paragraph
		var p []string
		for i < n {
			l2 := lines[i]
			if isBlank(l2) {
				break
			}
			if strings.HasPrefix(l2, "```") {
				break
			}
			if h, ok := headingHTML(l2); ok {
				_ = h
				break
			}
			if isRule(l2) {
				break
			}
			if strings.HasPrefix(l2, ">") {
				break
			}
			if it, ok := listItem(l2); ok && leadingSpaces(l2) == 0 {
				_ = it
				break
			}
			p = append(p, l2)
			i++
		}
		text := stripLeading(strings.Join(p, "\n"))
		*out = append(*out, "<p>"+inline(text)+"</p>")
	}
	return true
}

func parseBlocks(lines []string) []string {
	var out []string
	blockHTMLInto := func() {
		_ = parseBlocksInto(lines, &out)
	}
	blockHTMLInto()
	return out
}

func leadingSpaces(l string) int {
	i := 0
	for i < len(l) && l[i] == ' ' {
		i++
	}
	return i
}

// stripLeading removes leading spaces from each line of a multiline string.
func stripLeading(s string) string {
	lines := strings.Split(s, "\n")
	for i, l := range lines {
		lines[i] = strings.TrimLeft(l, " ")
	}
	return strings.Join(lines, "\n")
}

func firstWord(s string) string {
	f := strings.Fields(s)
	if len(f) == 0 {
		return ""
	}
	return f[0]
}

// headingHTML reports whether l is a heading line and returns its HTML.
func headingHTML(l string) (string, bool) {
	n := 0
	for n < len(l) && l[n] == '#' && n < 6 {
		n++
	}
	if n < 1 || n > 6 || n >= len(l) || l[n] != ' ' {
		// need 1-6 hashes, followed by a space, and not 7+ hashes
		m := 0
		for m < len(l) && l[m] == '#' {
			m++
		}
		if m >= 7 {
			return "", false
		}
		if n < 1 || n > 6 || (m < len(l) && l[m] != ' ') {
			return "", false
		}
		// note: "# " (hash, space, then end) allowed below
	}
	if n < 1 || n > 6 || n >= len(l) || l[n] != ' ' {
		return "", false
	}
	text := l[n+1:]
	text = strings.TrimRight(text, " ")
	for {
		j := len(text)
		for j > 0 && text[j-1] == '#' {
			j--
		}
		if j == len(text) {
			break // no trailing run of #
		}
		if j == 0 || text[j-1] != ' ' {
			break // run of # not preceded by a space
		}
		text = strings.TrimRight(text[:j], " ")
	}
	return "<h" + string(rune('0'+byte(n))) + ">" + inline(text) + "</h" + string(rune('0'+byte(n))) + ">", true
}

// isRule reports a horizontal rule line: 3+ of the same -, * or _, no spaces.
func isRule(l string) bool {
	if len(l) < 3 {
		return false
	}
	c := l[0]
	if c != '-' && c != '*' && c != '_' {
		return false
	}
	for _, r := range l {
		if r != rune(c) {
			return false
		}
	}
	return true
}

func dropQuote(l string) string {
	l = l[1:]
	if strings.HasPrefix(l, " ") {
		l = l[1:]
	}
	return l
}

// listItem strips the marker and returns the item text; ok is false if the
// line does not start with a list-item marker at column 0.
func listItem(l string) (string, bool) {
	if strings.HasPrefix(l, "- ") || strings.HasPrefix(l, "* ") || strings.HasPrefix(l, "+ ") {
		return l[2:], true
	}
	if idx := strings.IndexByte(l, '.'); idx >= 1 {
		d := l[:idx]
		allDigit := d != ""
		for _, r := range d {
			if r < '0' || r > '9' {
				allDigit = false
				break
			}
		}
		if allDigit && idx+1 < len(l) && l[idx+1] == ' ' {
			return l[idx+2:], true
		}
	}
	return "", false
}

// contLine renders a continuation line of a list item: up to 4 leading
// spaces are removed; if the result starts a list item it is a nested list,
// otherwise all leading spaces are removed and the text is joined with "\n".
func contLine(l string) string {
	s := l
	if c := leadingSpaces(s); c > 4 {
		s = s[4:]
	} else {
		s = s[c:]
	}
	if _, ok := listItem(s); ok {
		return "\n" + nestedListHTML(l)
	}
	return "\n" + strings.TrimLeft(l, " ")
}

// listHTML renders a run of top-level item lines (with continuations merged).
func listHTML(items []string) string {
	first, _ := listItem(items[0])
	_ = first
	tag := "ul"
	if idx := strings.IndexByte(items[0], '.'); idx >= 1 {
		tag = "ol"
		nums := items[0][:idx]
		start := 0
		for _, r := range nums {
			start = start*10 + int(r-'0')
		}
		if start != 1 {
			tag = `ol start="` + nums + `"`
		}
	}
	// parse each item: text and optional nested list
	type item struct {
		text  string
		nest  []string // nested item lines (raw)
	}
	var parsed []item
	for _, it := range items {
		p := item{text: strings.TrimLeft(it, " ")}
		for strings.HasPrefix(p.text, "\n") {
			// walk continuation lines stored after the first marker
		}
		// split off continuation lines
		segs := strings.Split(it, "\n")
		p.text = segs[0]
		p.nest = nil
		for _, s := range segs[1:] {
			_, isItem := listItem(s)
			if isItem {
				p.nest = append(p.nest, s)
			} else {
				p.text += "\n" + s
			}
		}
		parsed = append(parsed, p)
	}
	var b strings.Builder
	b.WriteString("<" + tag + ">\n")
	for i, p := range parsed {
		if i > 0 {
			b.WriteString("\n")
		}
		b.WriteString("<li>" + inline(p.text))
		if len(p.nest) > 0 {
			b.WriteString("\n")
			b.WriteString(listHTML(p.nest))
			b.WriteString("\n")
		}
		b.WriteString("</li>")
	}
	b.WriteString("\n</" + strings.SplitN(tag, ` start="`, 2)[0] + ">")
	return b.String()
}

// nestedListHTML renders a nested list given raw lines indented >= 2 spaces.
// The marker is found in the line with up to 4 leading spaces removed.
func nestedListHTML(rawLines []string) string {
	items := make([]string, 0, len(rawLines))
	for _, l := range rawLines {
		s := l
		if c := leadingSpaces(s); c > 4 {
			s = s[4:]
		} else {
			s = s[c:]
		}
		if t, ok := listItem(s); ok {
			items = append(items, t)
		}
	}
	return listHTML(items)
}

// ---------- inline ----------

// escapeText HTML-escapes &, <, > and ".
func escapeText(s string) string {
	r := strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;", `"`, "&quot;")
	return r.Replace(s)
}

// escapeWord escapes text but only & < > (attribute-value escaping).
func escapeWord(s string) string {
	r := strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;")
	return r.Replace(s)
}

// inline processes the inline syntax of a (possibly multiline) text.
func inline(s string) string {
	lineIs := strings.IndexFunc(s, func(r rune) bool { return r == '\n' })
	_ = lineIs
	// hard breaks and trailing spaces are handled per line
	var out []string
	lines := strings.Split(s, "\n")
	for i, l := range lines {
		br := false
		if i < len(lines)-1 {
			if strings.HasSuffix(l, `\`) {
				br = true
				l = l[:len(l)-1]
			} else if trailingSpaceCount(l) >= 2 {
				br = true
			}
		}
		l = strings.TrimRight(l, " ")
		if br {
			l += "<br />"
		}
		out = append(out, inlineLine(l))
	}
	return strings.Join(out, "\n")
}

func trailingSpaceCount(s string) int {
	n := 0
	for i := len(s) - 1; i >= 0 && s[i] == ' '; i-- {
		n++
	}
	return n
}

var punct = strings.NewReplacer(
	"&", "&amp;", "<", "&lt;", ">", "&gt;", `"`, "&quot;",
)

// inlineLine processes one line of inline syntax left to right.
func inlineLine(s string) string {
	// sort emphasis markers by position; process in order
	type mark struct {
		pos int
		kind string // "strong" or "em"
		ln  int // marker length (2 for strong, 1 for em)
	}
	var marks []mark
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '*' {
			if i+1 < len(s) && s[i+1] == '*' {
				marks = append(marks, mark{i, "strong", 2})
				i++
			} else {
				marks = append(marks, mark{i, "em", 1})
			}
		} else if c == '_' {
			marks = append(marks, mark{i, "em", 1})
		}
	}
	sort.SliceStable(marks, func(a, b int) bool { return marks[a].pos < marks[b].pos })
	// choose which markers to process: scan left to right, at the first
	// position where an opening marker may be followed by a later closing
	// one, process the earliest opener and its matching closer.
	out := inlineNoEmph(s)
	_ = out
	return inlineNoEmph(s)
}

// inlineNoEmph processes all inline constructs except strong/emphasis,
// leaving * and _ runs as literal text.
func inlineNoEmph(s string) string {
	var out strings.Builder
	var lit strings.Builder
	flush := func() {
		if lit.Len() > 0 {
			out.WriteString(escapeText(lit.String()))
			lit.Reset()
		}
	}
	for i := 0; i < len(s); {
		c := s[i]
		// backslash escape
		if c == '\\' && i+1 < len(s) && strings.IndexRune(escapeChars, rune(s[i+1])) >= 0 {
			flush()
			out.WriteString(escapeText(string(s[i+1])))
			i += 2
			continue
		}
		// code span
		if c == '`' {
			n := 0
			for i+n < len(s) && s[i+n] == '`' {
				n++
			}
			if j := findClose(s, i+n, n); j >= 0 {
				content := s[i+n : j]
				if len(content) >= 2 && content[0] == ' ' && content[len(content)-1] == ' ' &&
					strings.TrimSpace(content) != "" {
					content = content[1 : len(content)-1]
				}
				flush()
				out.WriteString("<code>" + escapeText(content) + "</code>")
				i += n + n
				// note: closer run is also length n
				i += 0
				i = j + n
				continue
			}
			lit.WriteString(s[i])
			i++
			continue
		}
		// autolink
		if c == '<' {
			rest := s[i+1:]
			var url string
			if strings.HasPrefix(rest, "http://") {
				url = "http://"
			} else if strings.HasPrefix(rest, "https://") {
				url = "https://"
			}
			if url != "" {
				tail := s[i+len(url):]
				end := strings.IndexAny(tail, " <>")
				if end >= 0 && end > 0 {
					u := url + tail[:end]
					flush()
					out.WriteString(`<a href="` + escapeWord(u) + `">` + escapeWord(u) + "</a>")
					i += len(url) + end + 1
					continue
				}
			}
			lit.WriteByte('<')
			i++
			continue
		}
		// link
		if c == '[' {
			if end := matchBracket(s, i); end > 0 {
				after := s[end+1:]
				if strings.HasPrefix(after, "(") {
					// find the closing paren of the (balanced) url/title part
					if p := findCloseParen(s, end+1); p >= 0 {
						target := s[end+2 : p]
						url, title := parseTarget(target)
						if url != "" {
							flush()
							out.WriteString(`<a href="` + escapeWord(url) + `"`)
							if title != "" {
								out.WriteString(` title="` + escapeText(title) + `"`)
							}
							out.WriteString(">" + inlineLinkText(s[i+1:end]) + "</a>")
							i = p + 1
							continue
						}
					}
				}
			}
			lit.WriteByte('[')
			i++
			continue
		}
		lit.WriteByte(c)
		i++
	}
	flush()
	return out.String()
}

// inlineLinkText processes link text with all syntax except links.
// (Code spans, autolinks, emphasis and escapes still apply.)
func inlineLinkText(s string) string {
	// disable link syntax: process as inline but skip link handling.
	// Approximation: run inlineNoEmph, which does not create links,
	// and additionally re-enable emphasis via the emphasis pass.
	return s
}

// parseTarget splits "url" or "url \"title\"" (no nested parens in url).
func parseTarget(t string) (url, title string) {
	t = strings.TrimSpace(t)
	if i := strings.IndexByte(t, '"'); i >= 0 {
		if j := strings.IndexByte(t[i+1:], '"'); j >= 0 {
			url = strings.TrimSpace(t[:i])
			title = t[i+1 : i+1+j]
			return url, title
		}
	}
	url = t
	return
}

// findClose finds the next run of exactly n backticks; returns its start
// index or -1.
func findClose(s string, from, n int) int {
	i := from
	for i < len(s) {
		if s[i] != '`' {
			i++
			continue
		}
		j := i
		for j < len(s) && s[j] == '`' {
			j++
		}
		if j-i == n {
			return i
		}
		i = j
	}
	return -1
}

// matchBracket returns the index of the matching ']' for the '[' at i,
// or -1.
func matchBracket(s string, i int) int {
	depth := 0
	for j := i; j < len(s); j++ {
		switch s[j] {
		case '[':
			depth++
		case ']':
			depth--
			if depth == 0 {
				return j
			}
		}
	}
	return -1
}

// findCloseParen returns the index of the ')' closing the '(' at i,
// honouring nested parentheses, or -1.
func findCloseParen(s string, i int) int {
	depth := 0
	for j := i; j < len(s); j++ {
		switch s[j] {
		case '(':
			depth++
		case ')':
			depth--
			if depth == 0 {
				return j
			}
		}
	}
	return -1
}
