			if startKind == -1 {
				startKind = it.kind
			}
			if it.kind != startKind {
				break // a different kind starts a new list
			}
			tops = append(tops, it)
			lastNest = nil
			lastNestIndent = -1
			i++
			continue
		}
		if sp >= 2 && len(tops) > 0 {
			s := l[min(sp, 4):]
			if isItemMarker(s) {
				it := parseItem(s)
				lastNest = append(lastNest, it)
				lastNestIndent = sp
